/* Family trees use the same character IDs, profiles and spoiler controls as the directory. */
let familyHouse='stark',familyQuery='',familyScale=1;
const familyLabels=new Set(['parent of','sibling of','married to','partner of','twin and lover of','raised as son','ward of','uncle of','grandparent of','publicly acknowledged as child']);
function houseMembers(h){const allowed=new Set(visible().map(n=>n.id));return [...h.rows.flat(),...h.other].filter(id=>allowed.has(id)&&!(h.id==='targaryen'&&['jon','lyanna-stark'].includes(id)&&level<6)&&!(h.id==='baelish'&&id==='lysa-arryn'&&level<3)&&!(h.id==='bolton'&&id==='sansa-stark'&&level<4));}
function houseRelations(h){const ids=new Set(houseMembers(h));return [...GOT_RELATIONS,...LORE_FAMILY_EXTRA].filter(e=>familyLabels.has(e[2])&&e[3]<=level&&ids.has(e[0])&&ids.has(e[1]));}
function familyKind(label){return label==='parent of'?'parent':['married to','partner of','twin and lover of'].includes(label)?'union':['sibling of','uncle of','grandparent of'].includes(label)?'kin':'household';}
function familyPerson(id,position=''){const n=entity(id);return `<button class="family-person" data-entity="${id}" ${position?`style="${position}"`:''}>${paintedCharacters.has(id)?`<img src="assets/paintings/${id}.jpg" alt="" width="42" height="52" loading="lazy">`:'<span class="family-initial" aria-hidden="true">'+esc(n.name.split(' ').map(w=>w[0]).slice(0,2).join(''))+'</span>'}<span><strong>${esc(n.name)}</strong><small>${n.grouped?'Grouped guide entry':'View character ↗'}</small></span></button>`;}
function familyDiagram(h){const ids=new Set(houseMembers(h)),rows=h.rows.map(r=>r.filter(id=>ids.has(id))).filter(r=>r.length),relations=houseRelations(h),w=Math.max(320,...rows.map(r=>r.length*190+70)),height=Math.max(220,rows.length*170+60),pos={};rows.forEach((r,i)=>r.forEach((id,j)=>pos[id]={x:(w-r.length*190)/2+j*190+10,y:60+i*170}));
 const paths=relations.filter(e=>pos[e[0]]&&pos[e[1]]).map((e,i)=>{const a=pos[e[0]],b=pos[e[1]],same=a.y===b.y;const ax=a.x+85,bx=b.x+85,ay=same?a.y:a.y+76,by=b.y;const mid=same?a.y-20-(i%3)*9:(ay+by)/2+(i%3)*6;return `<path class="family-edge ${familyKind(e[2])}" d="M ${ax} ${ay} C ${ax} ${mid},${bx} ${mid},${bx} ${by}"><title>${esc(entity(e[0]).name+' — '+e[2]+' — '+entity(e[1]).name)}</title></path>`}).join('');
 return `<div class="family-scroll" tabindex="0" aria-label="House ${h.name} family tree. Scroll horizontally to explore."><div class="family-size" style="width:${w*familyScale}px;height:${height*familyScale}px"><div class="family-canvas" style="width:${w}px;height:${height}px;transform:scale(${familyScale})"><svg width="${w}" height="${height}" aria-hidden="true">${paths}</svg>${Object.entries(pos).map(([id,p])=>familyPerson(id,`left:${p.x}px;top:${p.y}px`)).join('')}</div></div></div>`;
}
function houseMatches(){const q=familyQuery.trim().toLowerCase();return LORE_HOUSES.filter(h=>!q||h.name.toLowerCase().includes(q)||houseMembers(h).some(id=>entity(id).name.toLowerCase().includes(q)));}
function familyHouseList(){const matches=houseMatches();return `<p class="source" role="status">${matches.length} houses${familyQuery?' matching your search':''}</p><div class="house-grid">${matches.map(h=>`<button class="house-option ${h.id===familyHouse?'selected':''}" data-house="${h.id}" aria-pressed="${h.id===familyHouse}"><span class="house-monogram" aria-hidden="true">${h.name[0]}</span><span><strong>House ${h.name}</strong><small>${houseMembers(h).length} available ${houseMembers(h).length===1?'entry':'entries'}</small></span><span aria-hidden="true">↗</span></button>`).join('')||'<p class="note">No houses match. Try a house or a character name.</p>'}</div>`;}
function familyDetail(){const h=LORE_HOUSES.find(h=>h.id===familyHouse),ids=houseMembers(h),rels=houseRelations(h),other=h.other.filter(id=>ids.includes(id));return `<section class="family-panel" aria-labelledby="familyHeading"><div class="family-heading"><div><span class="eyebrow">BLOODLINES OF WESTEROS</span><h2 id="familyHeading" tabindex="-1">House ${h.name}</h2><p>${ids.length} available entries · ${rels.length} recorded relationships</p></div><div class="family-tools" aria-label="Tree zoom"><button class="outline" id="familyZoomOut" aria-label="Zoom out family tree" ${familyScale<=.6?'disabled':''}>−</button><button class="outline" id="familyReset">${Math.round(familyScale*100)}%</button><button class="outline" id="familyZoomIn" aria-label="Zoom in family tree" ${familyScale>=1.4?'disabled':''}>+</button></div></div><div class="family-legend"><span><i class="parent"></i>Parent → child</span><span><i class="union"></i>Marriage / partnership</span><span><i class="kin"></i>Other kinship</span><span><i class="household"></i>Raised / acknowledged</span></div>${ids.length?familyDiagram(h):'<div class="empty">No members available at your current viewing progress.</div>'}${other.length?`<div class="family-other"><h3>Other recorded members</h3><p>The guide does not provide enough ancestry to place these entries in a generation.</p><div class="family-other-grid">${other.map(id=>familyPerson(id)).join('')}</div></div>`:''}<div class="family-notes"><p>Read parent lines from top to bottom. Select a person to open their profile. Scroll sideways or use the zoom controls to explore wider trees.</p><p>Marriages and partnerships span different times in the story. A shared row does not imply siblings. Unconnected cards have no explicit family link in the supplied guide.</p>${h.id==='baratheon'?'<p>The royal children’s publicly acknowledged father is distinguished from biological parentage in the Lannister tree.</p>':''}${h.id==='targaryen'||h.id==='stark'?'<p>Later parentage revelations appear only when your viewing progress allows them.</p>':''}</div><details class="family-relationships"><summary>Read all ${rels.length} family relationships</summary>${rels.length?`<ul>${rels.map(e=>`<li><button data-entity="${e[0]}">${esc(entity(e[0]).name)}</button><span>${esc(e[2])}</span><button data-entity="${e[1]}">${esc(entity(e[1]).name)}</button></li>`).join('')}</ul>`:'<p>No explicit family relationships are recorded for these members at this viewing progress.</p>'}</details></section>`;}
function bindFamilyDetail(){wire();$('#familyZoomOut').onclick=()=>{familyScale=Math.max(.6,Math.round((familyScale-.2)*10)/10);updateFamilyDetail()};$('#familyZoomIn').onclick=()=>{familyScale=Math.min(1.4,Math.round((familyScale+.2)*10)/10);updateFamilyDetail()};$('#familyReset').onclick=()=>{familyScale=1;updateFamilyDetail()};}
function updateFamilyDetail(){$('#familyDetail').innerHTML=familyDetail();bindFamilyDetail();}
function bindHouseList(){$$('[data-house]').forEach(b=>b.onclick=()=>{familyHouse=b.dataset.house;familyScale=1;$('#houseList').innerHTML=familyHouseList();bindHouseList();updateFamilyDetail();$('#familyHeading').focus({preventScroll:true});$('#familyDetail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});}
const preFamilyRender=render;
render=()=>{if(universe!=='got'||view!=='Family Trees'){preFamilyRender();return}refreshChrome();$('#main').innerHTML=title('Every house. Every family tie.','Explore the great houses and the smaller families named in your HBO reference.',referenceButtons())+`<section class="family-intro"><span class="eyebrow">THE HOUSES OF THE REALM</span><h2>A name carries a history.</h2><p>Trace parents, children, marriages, and the ties that cross house boundaries. Familiar houses come first; select any house below to explore.</p><div class="family-stat"><strong>${LORE_HOUSES.length}</strong> houses in the guide <span>·</span> <strong>${data().levels[level]}</strong> viewing progress</div></section><div class="family-search"><label for="houseSearch">Find a house or family member</label><input id="houseSearch" type="search" placeholder="Try Stark, Mormont, or Sansa…" value="${esc(familyQuery)}"></div><details class="house-picker" open><summary>Choose a house</summary><div id="houseList">${familyHouseList()}</div></details><div id="familyDetail">${familyDetail()}</div><p class="source">Source: your supplied Game of Thrones reference, especially sections 1–9 and 12. This is a map of its recorded families, not an exhaustive history of every ancestor. Grouped entries stay grouped. The existing viewing-progress setting applies.</p>`;bindHouseList();bindFamilyDetail();$('#houseSearch').oninput=e=>{familyQuery=e.target.value;$('#houseList').innerHTML=familyHouseList();bindHouseList()};};
const familyNav=document.createElement('button');familyNav.dataset.view='Family Trees';familyNav.dataset.gotOnly='';familyNav.setAttribute('aria-label','Family trees');familyNav.innerHTML='<i>♧</i>Family trees';familyNav.onclick=()=>go('Family Trees');$('nav [data-view="Characters"]').after(familyNav);
render();
